local password = {}

local digest = require('digest')
local uuid = require('uuid')
local validator = require('authman.validator')
local utils = require('authman.utils.utils')

local CHAR_GROUP_PATTERNS = {
    '[%l]',   -- lower case
    '[%u]',   -- upper case
    '[%d]',   -- didgets
    '[!@#&_=;:,/\\|`~ %?%+%-%.%^%%%$%*]',  -- ! @ # & _ = ; : , / \ | ` ~ ? + - . ^ % $ *
}

local STRENGTH = {
    none = {
        min_len = 0,
        min_group = 0,
    },
    whocares = {
        min_len = 2,
        min_group = 1,
    },
    easy = {
        min_len = 6,
        min_group = 2,
    },
    common = {   -- default pattern
        min_len = 8,
        min_group = 2,
    },
    moderate = {
        min_len = 12,
        min_group = 3,
    },
    violence = {
        min_len = 16,
        min_group = 4,
    },
    nightmare = {
        min_len = 24,
        min_group = 4,
    },
}

-----
-- password (id, user_id, password)
-----
function password.model(config)
    local model = {}

    model.SPACE_NAME = config.spaces.password.name

    model.PRIMARY_INDEX = 'primary'
    model.USER_ID_INDEX = 'user'

    model.ID = 1
    model.USER_ID = 2
    model.HASH = 3

    function model.get_space()
        return box.space[model.SPACE_NAME]
    end

    function model.get_by_id(id)
        return model.get_space():get(id)
    end

    function model.get_by_user_id(user_id)
        if validator.not_empty_string(user_id) then
            -- TODO create index and migrations
            return model.get_space().index[model.USER_ID_INDEX]:select({user_id})[1]
        end
    end

    function model.delete_by_user_id(user_id)
        if validator.not_empty_string(user_id) then
            return model.get_space().index[model.USER_ID_INDEX]:delete({user_id})
        end
    end

    function model.hash(password, salt)
        return utils.salted_hash(password, salt)
    end

    function model.is_valid(raw_password, user_id)
        local password_tuple = model.get_by_user_id(user_id)
        if password_tuple == nil then
            return false
        end

        return password_tuple[model.HASH] == model.hash(raw_password, user_id)
    end

    function model.create(password_tuple)
        local id = uuid.str()
        return model.get_space():insert({
            id,
            password_tuple[model.USER_ID],
            password_tuple[model.HASH],
        })
    end

    function model.update(password_tuple)
        local social_id, fields
        social_id = password_tuple[model.ID]
        fields = utils.format_update(password_tuple)
        return model.get_space():update(social_id, fields)
    end

    function model.create_or_update(password_tuple)
        local user_id = password_tuple[model.USER_ID]
        local exists_password_tuple = model.get_by_user_id(user_id)
        if exists_password_tuple == nil then
            return model.create(password_tuple)
        else
            password_tuple[model.ID] = exists_password_tuple[model.ID]
            return model.update(password_tuple)
        end
    end

    function model.strong_enough(password)
        local min_len = STRENGTH[config.password_strength]['min_len']
        local min_group = STRENGTH[config.password_strength]['min_group']

        if min_len ~= nil and string.len(password) < min_len then
            return false
        end

        if min_group ~= nil then
            local char_group_count = 0
            for _, pattern in pairs(CHAR_GROUP_PATTERNS) do
                if string.match(password, pattern) then
                    char_group_count = char_group_count + 1
                end
            end

            if char_group_count < min_group then
                return false
            end
        end

        return true
    end

    return model
end

return password

local consumer = {}

local validator =  require('authman.validator')
local utils = require('authman.utils.utils')
local uuid = require('uuid')


-----
-- oauth_consumer (id, secret, app_id, redirect_urls)
-----
function consumer.model(config)

    local model = {}
    model.SPACE_NAME = config.spaces.oauth_consumer.name

    model.PRIMARY_INDEX = 'primary'
    model.APP_ID_INDEX = 'app'

    model.ID = 1
    model.SECRET_HASH = 2
    model.APP_ID = 3
    model.REDIRECT_URLS = 4 -- blank space separated list

    model.CONSUMER_SECRET_LEN = 32

    function model.get_space()
        return box.space[model.SPACE_NAME]
    end

    function model.serialize(consumer_tuple, data)
        if consumer_tuple == nil then
            return {}
        end

        local result = {
            consumer_key = consumer_tuple[model.ID],
            consumer_secret_hash = consumer_tuple[model.SECRET_HASH],
            app_id = consumer_tuple[model.APP_ID],
            redirect_urls = consumer_tuple[model.REDIRECT_URLS],
        }
        if data ~= nil then
            for k,v in pairs(data) do
                result[k] = v
            end
        end

        return result
    end


    function model.create(id, secret, app_id, redirect_urls)

        return model.get_space():insert{
            id,
            utils.salted_hash(secret, app_id),
            app_id,
            redirect_urls,
        }
    end

    function model.get_by_id(id)
        if validator.not_empty_string(id) then
            return model.get_space():get(id)
        end
    end

    function model.get_by_app_id(app_id)
        if validator.not_empty_string(app_id) then
            return model.get_space().index[model.APP_ID_INDEX]:get(app_id)
        end
    end

    function model.generate_consumer_key()
        return string.hex(uuid.bin())
    end

    function model.generate_consumer_secret()
        return utils.gen_random_key(model.CONSUMER_SECRET_LEN) 
    end

    function model.update_consumer_secret(consumer_key, consumer_secret, app_id)
        local consumer_secret_hash = utils.salted_hash(consumer_secret, app_id)
        return model.get_space():update(consumer_key, {{'=', model.SECRET_HASH, consumer_secret_hash}})
    end

    function model.delete_by_app_id(app_id)
        if validator.not_empty_string(app_id) then
            return model.get_space().index[model.APP_ID_INDEX]:delete(app_id)
        end
    end

    return model
end

return consumer

